SourceCode.Declaration:
/// <summary>
/// The <c>AVAWHSProcessGuidePromptPostCoilCalculatorStep</c> represents a step that post the data from calculator
/// </summary>
[
    ProcessGuideStepName(classStr(AVAWHSProcessGuidePostCoilCalculatorStep))
]
class AVAWHSProcessGuidePostCoilCalculatorStep extends ProcessGuideStepWithoutPrompt
{
}

Method.Source:
protected void doExecute()
{
    WhsrfPassthrough        avaPass;
    InventTable             avaInventTable;
    UnitOfMeasureSymbol     avaKilogramsSymbol;
    WHSAdjustmentTypeCode   avaAdjustmentTypeCode;


    avaPass         = controller.parmSessionState().parmPass();
    avaInventTable  = InventTable::find(avaPass.parmItemId());

    avaKilogramsSymbol = UnitOfMeasureInternalCode::avaCodeSymbol2Symbol(UnitOfMeasureCodeSymbol::Kilograms);

    if (!avaKilogramsSymbol)
    {
        throw error("@SYS309696");
    }

    avaPass.insert(ProcessGuideDataTypeNames::UOM, avaKilogramsSymbol);

    if (avaPass.parmLicensePlateId())
    {
        avaPass.insert(ProcessGuideDataTypeNames::LPAdjustIn, avaPass.parmLicensePlateId());
    }

    avaPass.insert(ProcessGuideDataTypeNames::QtyWithScanningLimit, avaPass.avaParmCoilWeight()); 
    avaPass.insert(ProcessGuideDataTypeNames::Qty, abs(avaPass.avaParmCoilWeight()));

    avaAdjustmentTypeCode = WHSRFMenuItemTable::getDefaultAdjustmentTypeCode(avaPass.lookupStr(ProcessGuideDataTypeNames::MenuItem)); 

    if (avaAdjustmentTypeCode)
    {
        avaPass.insert(ProcessGuideDataTypeNames::AdjustmentType, avaAdjustmentTypeCode);
        avaPass.insert(ProcessGuideDataTypeNames::SelectedAdjustmentType, avaAdjustmentTypeCode);
    }

    super();

}
